--
-- Name: append_initial_status_incident_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_initial_status_incident_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO status_incident_updates (
        incident_id, lifecycle_state, message, posted_at, actor, idempotency_key
    ) VALUES (
        NEW.id,
        NEW.lifecycle_state,
        COALESCE(NULLIF(btrim(NEW.message), ''), NEW.title),
        NEW.posted_at,
        NEW.created_by,
        NEW.create_idempotency_key
    ) ON CONFLICT (idempotency_key) DO NOTHING;
    RETURN NEW;
END;
$$;


--
-- Name: append_legacy_status_incident_resolution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_legacy_status_incident_resolution() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.resolved_at IS NULL AND NEW.resolved_at IS NOT NULL THEN
        INSERT INTO status_incident_updates (
            incident_id, lifecycle_state, message, posted_at, actor, idempotency_key
        ) SELECT NEW.id, NEW.lifecycle_state, 'Resolved', NEW.resolved_at, 'legacy-api',
                 'legacy-resolve:' || NEW.id::text
          WHERE NOT EXISTS (
              SELECT 1 FROM status_incident_updates
              WHERE incident_id = NEW.id
                AND lifecycle_state = NEW.lifecycle_state
                AND posted_at = NEW.resolved_at
          )
        ON CONFLICT (idempotency_key) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: apps_bump_cpu_policy_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_bump_cpu_policy_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.cpu_millicores IS DISTINCT FROM OLD.cpu_millicores THEN
        NEW.app_cpu_policy_revision := OLD.app_cpu_policy_revision + 1;
    ELSE
        NEW.app_cpu_policy_revision := OLD.app_cpu_policy_revision;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: apps_bump_egress_allowlist_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_bump_egress_allowlist_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.egress_allowlist IS DISTINCT FROM OLD.egress_allowlist
       OR NEW.egress_ports IS DISTINCT FROM OLD.egress_ports THEN
        NEW.egress_allowlist_revision := OLD.egress_allowlist_revision + 1;
    ELSE
        -- Callers cannot forge a revision by setting the bookkeeping column.
        NEW.egress_allowlist_revision := OLD.egress_allowlist_revision;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: apps_bump_scaling_policy_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_bump_scaling_policy_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF ROW(
        NEW.min_instances,
        NEW.max_concurrency,
        NEW.idle_timeout_s,
        NEW.autoscale_target_rps,
        NEW.autoscale_target_cpu_pct,
        NEW.scaling_policy,
        NEW.workload_class,
        NEW.node_id
    ) IS DISTINCT FROM ROW(
        OLD.min_instances,
        OLD.max_concurrency,
        OLD.idle_timeout_s,
        OLD.autoscale_target_rps,
        OLD.autoscale_target_cpu_pct,
        OLD.scaling_policy,
        OLD.workload_class,
        OLD.node_id
    ) THEN
        NEW.scaling_policy_revision := OLD.scaling_policy_revision + 1;
    ELSE
        -- Callers cannot forge a revision by setting the bookkeeping column.
        NEW.scaling_policy_revision := OLD.scaling_policy_revision;
    END IF;
    RETURN NEW;
END;
$$;


