-- Name: instances_started_at_set(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.instances_started_at_set() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.started_at is null then
    new.started_at = now();
  end if;
  return new;
end
$$;


--
-- Name: invocation_done_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invocation_done_notify() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
    payload jsonb;
begin
    if (tg_op = 'UPDATE' and old.state in ('pending','dispatching')
        and new.state in ('completed','failed','cancelled')) then
        payload := jsonb_build_object(
            'invocation_id', new.id::text,
            'app_id', new.app_id::text,
            'source', new.source,
            'state', new.state
        );
        perform pg_notify('invocation_done', payload::text);
    end if;
    return new;
end;
$$;


--
-- Name: invocation_due_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invocation_due_notify() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
    payload jsonb;
begin
    payload := jsonb_build_object(
        'invocation_id', new.id::text,
        'app_id', new.app_id::text,
        'source', new.source
    );
    perform pg_notify('invocation_due', payload::text);
    return new;
end;
$$;


--
-- Name: job_tasks_notify_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_tasks_notify_v2() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    channel text;
    payload jsonb;
BEGIN
    IF TG_OP = 'INSERT' AND NEW.status = 'queued' THEN
        channel := 'job_tasks_queued';
        payload := jsonb_build_object(
            'v', 1,
            'op', TG_OP,
            'run_id', NEW.run_id,
            'task_index', NEW.task_index,
            'attempt', NEW.attempt
        );
    ELSIF TG_OP = 'UPDATE'
        AND OLD.status = 'queued' AND NEW.status = 'claimed' THEN
        channel := 'job_tasks_dispatched';
        payload := jsonb_build_object(
            'v', 1,
            'op', TG_OP,
            'run_id', NEW.run_id,
            'task_index', NEW.task_index,
            'attempt', NEW.attempt,
            'instance_id', NEW.instance_id,
            'lease_token', NEW.lease_token
        );
    ELSIF TG_OP = 'UPDATE'
        AND OLD.status IN ('queued', 'claimed')
        AND NEW.status IN ('succeeded', 'failed', 'timeout', 'cancelled', 'oom') THEN
        channel := 'job_tasks_terminal';
        payload := jsonb_build_object(
            'v', 1,
            'op', TG_OP,
            'run_id', NEW.run_id,
            'task_index', NEW.task_index,
            'attempt', NEW.attempt,
            'status', NEW.status,
            'exit_code', NEW.exit_code,
            'error_class', NEW.error_class,
            'finished_at', NEW.finished_at
        );
    ELSE
        RETURN NEW;
    END IF;

    PERFORM pg_notify(channel, payload::text);
    RETURN NEW;
END;
$$;


--
-- Name: managed_realtime_channel_route_targets_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.managed_realtime_channel_route_targets_notify() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    if tg_table_name in ('managed_realtime_channel_routes', 'managed_realtime_channel_route_overflow_channels') then
        if tg_op = 'DELETE' then
            perform pg_notify(
                'managed_realtime_channel_route_targets_changed',
                json_build_object('endpoint_id', old.endpoint_id::text, 'channel', old.channel)::text
            );
        elsif tg_op = 'INSERT' then
            perform pg_notify(
                'managed_realtime_channel_route_targets_changed',
                json_build_object('endpoint_id', new.endpoint_id::text, 'channel', new.channel)::text
            );
        else
            perform pg_notify(
                'managed_realtime_channel_route_targets_changed',
                json_build_object('endpoint_id', old.endpoint_id::text, 'channel', old.channel)::text
            );
            if (old.endpoint_id, old.channel) is distinct from (new.endpoint_id, new.channel) then
                perform pg_notify(
                    'managed_realtime_channel_route_targets_changed',
                    json_build_object('endpoint_id', new.endpoint_id::text, 'channel', new.channel)::text
                );
            end if;
        end if;
    elsif tg_table_name = 'managed_realtime_channel_route_overflow' then
        if tg_op = 'DELETE' then
            perform pg_notify(
                'managed_realtime_channel_route_targets_changed',
                json_build_object('endpoint_id', old.endpoint_id::text)::text
            );
        elsif tg_op = 'INSERT' then
            perform pg_notify(
                'managed_realtime_channel_route_targets_changed',
                json_build_object('endpoint_id', new.endpoint_id::text)::text
            );
        else
            perform pg_notify(
                'managed_realtime_channel_route_targets_changed',
                json_build_object('endpoint_id', old.endpoint_id::text)::text
            );
            if old.endpoint_id is distinct from new.endpoint_id then
                perform pg_notify(
                    'managed_realtime_channel_route_targets_changed',
                    json_build_object('endpoint_id', new.endpoint_id::text)::text
                );
            end if;
        end if;
    else
        perform pg_notify('managed_realtime_channel_route_targets_changed', '{}');
    end if;
    return null;
end;
$$;


