--
-- Name: outbound_integrations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.outbound_integrations (
    id uuid NOT NULL,
    account_id uuid NOT NULL,
    name text NOT NULL,
    origin text NOT NULL,
    token_hash bytea NOT NULL,
    rate_per_second double precision NOT NULL,
    burst integer NOT NULL,
    max_in_flight integer NOT NULL,
    request_timeout_ms integer NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    provider_auth_mode text DEFAULT 'application'::text NOT NULL,
    allowed_methods text[] DEFAULT ARRAY[]::text[] NOT NULL,
    allowed_path_prefixes text[] DEFAULT ARRAY[]::text[] NOT NULL,
    credential_source text DEFAULT 'operator_env'::text NOT NULL,
    owner_kind text DEFAULT 'operator'::text NOT NULL,
    daily_request_limit bigint,
    max_retries integer DEFAULT 0 NOT NULL,
    circuit_breaker_failure_threshold integer DEFAULT 0 NOT NULL,
    circuit_breaker_open_seconds integer DEFAULT 0 NOT NULL,
    retry_budget_per_minute integer DEFAULT 0 NOT NULL,
    response_cache_ttl_seconds integer DEFAULT 0 NOT NULL,
    runs_enabled boolean DEFAULT false NOT NULL,
    CONSTRAINT outbound_customer_integration_policy_chk CHECK (((owner_kind <> 'customer'::text) OR ((provider_auth_mode = 'managed'::text) AND (credential_source = 'customer_sealed'::text) AND ((cardinality(allowed_methods) >= 1) AND (cardinality(allowed_methods) <= 6)) AND ((cardinality(allowed_path_prefixes) >= 1) AND (cardinality(allowed_path_prefixes) <= 32))))),
    CONSTRAINT outbound_integrations_allowed_methods_count_chk CHECK ((cardinality(allowed_methods) <= 6)),
    CONSTRAINT outbound_integrations_allowed_path_prefixes_count_chk CHECK ((cardinality(allowed_path_prefixes) <= 32)),
    CONSTRAINT outbound_integrations_burst_check CHECK ((burst > 0)),
    CONSTRAINT outbound_integrations_circuit_breaker_policy_chk CHECK ((((circuit_breaker_failure_threshold = 0) AND (circuit_breaker_open_seconds = 0)) OR (((circuit_breaker_failure_threshold >= 1) AND (circuit_breaker_failure_threshold <= 20)) AND ((circuit_breaker_open_seconds >= 1) AND (circuit_breaker_open_seconds <= 300))))),
    CONSTRAINT outbound_integrations_credential_source_chk CHECK ((credential_source = ANY (ARRAY['operator_env'::text, 'customer_sealed'::text]))),
    CONSTRAINT outbound_integrations_daily_request_limit_chk CHECK (((daily_request_limit IS NULL) OR ((daily_request_limit >= 1) AND (daily_request_limit <= 100000000)))),
    CONSTRAINT outbound_integrations_max_in_flight_check CHECK ((max_in_flight > 0)),
    CONSTRAINT outbound_integrations_max_retries_chk CHECK (((max_retries >= 0) AND (max_retries <= 2))),
    CONSTRAINT outbound_integrations_name_check CHECK (((length(name) >= 1) AND (length(name) <= 127))),
    CONSTRAINT outbound_integrations_origin_check CHECK ((origin ~ '^https://[^/?#]+(/[^?#]*)?$'::text)),
    CONSTRAINT outbound_integrations_owner_kind_chk CHECK ((owner_kind = ANY (ARRAY['operator'::text, 'customer'::text]))),
    CONSTRAINT outbound_integrations_provider_auth_mode_chk CHECK ((provider_auth_mode = ANY (ARRAY['application'::text, 'managed'::text]))),
    CONSTRAINT outbound_integrations_rate_per_second_check CHECK ((rate_per_second > (0)::double precision)),
    CONSTRAINT outbound_integrations_request_timeout_ms_check CHECK ((request_timeout_ms > 0)),
    CONSTRAINT outbound_integrations_response_cache_ttl_chk CHECK (((response_cache_ttl_seconds >= 0) AND (response_cache_ttl_seconds <= 300))),
    CONSTRAINT outbound_integrations_retry_budget_chk CHECK (((retry_budget_per_minute >= 0) AND (retry_budget_per_minute <= 3000))),
    CONSTRAINT outbound_integrations_token_hash_check CHECK ((octet_length(token_hash) = 32))
);


