--
-- Name: trigger_records; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.trigger_records (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    trigger_id uuid NOT NULL,
    item_identifier text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    headers jsonb DEFAULT '{}'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    next_fire_at timestamp with time zone DEFAULT now() NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    last_error text,
    last_dispatched_at timestamp with time zone,
    deadline_at timestamp with time zone,
    retry_policy jsonb,
    result_retention_until timestamp with time zone,
    claim_generation bigint DEFAULT 0 NOT NULL,
    claim_expires_at timestamp with time zone,
    work_policy_name text,
    work_key_digest bytea,
    work_sequence bigint,
    work_policy_revision bigint,
    work_fairness_digest bytea,
    work_fairness_limit integer,
    work_expires_at timestamp with time zone,
    CONSTRAINT trigger_records_attempts_check CHECK (((attempts >= 0) AND (attempts <= 25))),
    CONSTRAINT trigger_records_claim_generation_check CHECK ((claim_generation >= 0)),
    CONSTRAINT trigger_records_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'claimed'::text, 'succeeded'::text, 'retry'::text, 'dead_letter'::text, 'superseded'::text, 'cancelled'::text, 'expired'::text]))),
    CONSTRAINT trigger_records_work_lane_check CHECK ((((work_policy_name IS NULL) AND (work_key_digest IS NULL) AND (work_sequence IS NULL) AND (work_policy_revision IS NULL) AND (work_fairness_digest IS NULL) AND (work_fairness_limit IS NULL) AND (work_expires_at IS NULL)) OR ((work_policy_name IS NOT NULL) AND (work_policy_name ~ '^[a-z][a-z0-9-]{0,62}$'::text) AND (work_key_digest IS NOT NULL) AND (length(work_key_digest) = 32) AND (work_sequence IS NOT NULL) AND (work_sequence > 0) AND (work_policy_revision IS NOT NULL) AND (work_policy_revision > 0) AND (((work_fairness_digest IS NULL) AND (work_fairness_limit IS NULL)) OR ((work_fairness_digest IS NOT NULL) AND (length(work_fairness_digest) = 32) AND (work_fairness_limit IS NOT NULL) AND ((work_fairness_limit >= 1) AND (work_fairness_limit <= 1000)))))))
);


