--

CREATE TABLE public.workflow_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid NOT NULL,
    event_name text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: workflow_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    app_id uuid NOT NULL,
    workflow_name text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    current_step text,
    input jsonb DEFAULT '{}'::jsonb NOT NULL,
    output jsonb,
    definition_snapshot jsonb NOT NULL,
    scheduled_for timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_until timestamp with time zone,
    CONSTRAINT workflow_runs_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'awaiting_event'::text, 'succeeded'::text, 'failed'::text, 'dead'::text])))
);


--
-- Name: workflow_step_attempts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_step_attempts (
    run_id uuid NOT NULL,
    step_name text NOT NULL,
    attempt integer NOT NULL,
    status text NOT NULL,
    http_status integer,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    next_attempt_at timestamp with time zone,
    error text,
    CONSTRAINT workflow_step_attempts_attempt_check CHECK ((attempt > 0)),
    CONSTRAINT workflow_step_attempts_http_status_check CHECK (((http_status >= 100) AND (http_status <= 599))),
    CONSTRAINT workflow_step_attempts_status_check CHECK ((status = ANY (ARRAY['running'::text, 'retrying'::text, 'succeeded'::text, 'failed'::text])))
);


--
-- Name: workflow_steps; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_steps (
    run_id uuid NOT NULL,
    step_name text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempt integer DEFAULT 0 NOT NULL,
    input jsonb,
    output jsonb,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    next_check_at timestamp with time zone,
    next_retry_at timestamp with time zone,
    CONSTRAINT workflow_steps_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'awaiting_event'::text, 'succeeded'::text, 'failed'::text, 'dead'::text, 'skipped'::text])))
);


